//===- softmax.cu - PolyKernel generated Softmax kernel ----------*- CUDA -*-===//
//
// AUTO-GENERATED by `polykernel-opt --lower-to-cuda` (Todo 10 / Wave 2).
// Do not edit by hand; re-run the pass to regenerate.
//
// Numerically STABLE softmax over the last axis (one block per row):
//     pass 1: m = max(x)               (warp-shuffle + shared-mem reduction)
//     pass 2: s = sum(exp(x - m))      (reduction)
//     pass 3: y = exp(x - m) / s, rounded to bf16.
// Subtracting the row max before exp keeps the exponentials bounded (matches
// tests/golden/golden.py). bf16 in/out, fp32 compute (the golden rounding
// contract). Written against the portable template (kernel_common.h) so it
// compiles UNCHANGED under `nvcc -DPOLYKERNEL_CUDA` and `hipcc -DPOLYKERNEL_HIP`.
//
//===----------------------------------------------------------------------===//

#include "../template/kernel_common.h"

#include <cfloat>

namespace {

constexpr int kBlockThreads = 256;
constexpr int kNumWarps = kBlockThreads / PK_WARP_SIZE;

// Butterfly warp reductions; the result lands in every lane of the warp.
PK_DEVICE_INLINE float warp_reduce_sum(float v) {
#pragma unroll
  for (int offset = PK_WARP_SIZE / 2; offset > 0; offset >>= 1)
    v += pk_shfl_xor_sync(v, offset);
  return v;
}
PK_DEVICE_INLINE float warp_reduce_max(float v) {
#pragma unroll
  for (int offset = PK_WARP_SIZE / 2; offset > 0; offset >>= 1)
    v = fmaxf(v, pk_shfl_xor_sync(v, offset));
  return v;
}

// Block reductions: per-warp partials -> shared -> warp 0 finalizes. The result
// is returned in every lane of warp 0 (thread 0 in particular). Sum and max share
// the butterfly shape; the idle-lane pad is the combiner's identity (0.0f for
// sum, -FLT_MAX for max).

// Block sum reduction (mirrors rmsnorm's block_reduce_sum).
PK_DEVICE float block_reduce_sum(float v, float *warp_sums) {
  int lane = threadIdx.x & (PK_WARP_SIZE - 1);
  int warp = threadIdx.x / PK_WARP_SIZE;
  v = warp_reduce_sum(v);
  if (lane == 0)
    warp_sums[warp] = v;
  pk_syncthreads();
  v = (threadIdx.x < kNumWarps) ? warp_sums[lane] : 0.0f;
  if (warp == 0)
    v = warp_reduce_sum(v);
  return v;
}

// Concrete block max reduction (same shape, fmaxf combiner, -FLT_MAX identity).
PK_DEVICE float block_reduce_max(float v, float *warp_maxes) {
  int lane = threadIdx.x & (PK_WARP_SIZE - 1);
  int warp = threadIdx.x / PK_WARP_SIZE;
  v = warp_reduce_max(v);
  if (lane == 0)
    warp_maxes[warp] = v;
  pk_syncthreads();
  v = (threadIdx.x < kNumWarps) ? warp_maxes[lane] : -FLT_MAX;
  if (warp == 0)
    v = warp_reduce_max(v);
  return v;
}

// One block per row (last-axis reduction). Scalar strided loads (no vector tail
// needed: an odd `cols` is handled because each thread strides by kBlockThreads
// and the per-element bounds `i < cols` cover the trailing element exactly).
PK_GLOBAL void softmax_kernel(const pk_bf16 *__restrict__ input,
                              pk_bf16 *__restrict__ output, int cols) {
  PK_SHARED float warp_partials[kNumWarps];
  PK_SHARED float s_max;
  PK_SHARED float s_sum;

  const int row = blockIdx.x;
  const int tid = threadIdx.x;
  const pk_bf16 *xrow = input + static_cast<size_t>(row) * cols;
  pk_bf16 *yrow = output + static_cast<size_t>(row) * cols;

  // Pass 1: row max in fp32 (bf16 input upcast exactly to fp32).
  float local_max = -FLT_MAX;
  for (int i = tid; i < cols; i += kBlockThreads)
    local_max = fmaxf(local_max, pk_bf162float(xrow[i]));
  float row_max = block_reduce_max(local_max, warp_partials);
  if (tid == 0)
    s_max = row_max;
  pk_syncthreads();
  float m = s_max;

  // Pass 2: sum of exp(x - m) in fp32.
  float local_sum = 0.0f;
  for (int i = tid; i < cols; i += kBlockThreads)
    local_sum += expf(pk_bf162float(xrow[i]) - m);
  float row_sum = block_reduce_sum(local_sum, warp_partials);
  if (tid == 0)
    s_sum = row_sum;
  pk_syncthreads();
  float inv_sum = 1.0f / s_sum;

  // Pass 3: normalize, round back to bf16 (RNE), store.
  for (int i = tid; i < cols; i += kBlockThreads)
    yrow[i] = pk_float2bf16(expf(pk_bf162float(xrow[i]) - m) * inv_sum);
}

} // namespace

// Host-callable launch entry (the launch_*-style ABI). Softmax over the LAST axis
// (the golden default axis=-1): `rows` length-`cols` rows are reduced
// independently; the caller flattens all leading dims into `rows`. The stream is
// passed as void* to keep the signature backend-agnostic and cast to the backend
// stream type (pk_stream_t) inside.
void launch_softmax(const pk_bf16 *input, pk_bf16 *output, int rows, int cols,
                    void *stream) {
  pk_stream_t s = static_cast<pk_stream_t>(stream);
  PK_LAUNCH(softmax_kernel, dim3(rows), dim3(kBlockThreads), 0, s, input, output,
            cols);
  PK_CHECK(pk_get_last_error());
}
